func allow_request(limiter: WindowLimiter, now: Int) -> Bool {
  // Check if the limiter's internal state is reset
  if limiter.state == "reset" {
    // Allow the request if the time difference is within the allowed window
    return now - limiter.start_time <= limiter.window
  }
  // Update the limiter's internal state to "active"
  limiter.state = "active"
  // Reject the request if the limiter is not reset
  return false
}
