def encode_runs(text):
    if not text:
        return ""

    compressed = []
    i = 0

    while i < len(text):
        current_char = text[i]
        count = 1

        # Increment until the next character is different
        while i + 1 < len(text) and text[i + 1] == current_char:
            i += 1
            count += 1

        # Check if the run is longer than 1 character
        if count > 1:
            compressed.append(f"{count}{current_char}")
        else:
            compressed.append(current_char)

        i += 1

    return "".join(compressed)
```

